<script setup lang="ts">
import {normalizeTheme} from '@/domain/normalize-theme';import {ref,onMounted,onUnmounted} from 'vue';import {onShow,onHide,onBackPress} from '@dcloudio/uni-app';import AppExperience from './AppExperience.vue';import defaults from '@/domain/default-theme.json';import type {Theme,Vod,Category,Platform} from '@/domain/types';import {api} from '@/services/api';
const props=withDefaults(defineProps<{device?:Platform}>(),{device:'mobile'});const theme=ref<Theme>(JSON.parse(JSON.stringify(defaults))),items=ref<Vod[]>([]),categories=ref<Category[]>([]),sectionItems=ref<Record<string,Vod[]>>({}),demo=ref(false),error=ref(''),locked=ref(false),loading=ref(true);const experience=ref<any>(null),templateKey=ref('');let version='',timer:ReturnType<typeof setInterval>|undefined,running=false;
async function load(){if(running)return;running=true;try{const t=await api.theme(props.device);locked.value=false;templateKey.value=t.template;const signature=t.template+':'+t.version;if(signature!==version){theme.value=normalizeTheme(t.theme);version=signature;}const h=await api.health();demo.value=!h.cmsConfigured;if(demo.value){items.value=[];categories.value=[];sectionItems.value={};}else{const [c,k]=await Promise.all([api.catalog(),api.categories()]);items.value=c.items;categories.value=k.items;const groups:Record<string,Vod[]>={};await Promise.all(theme.value.sections.filter(s=>s.enabled&&((s.source==='category'&&s.categoryId)||(s.orderBy==='manual'&&s.manualIds))).map(async s=>{groups[s.id]=(await api.catalog(1,'',s.source==='category'?s.categoryId:'',s.orderBy==='manual'?s.manualIds||'':'')).items;}));sectionItems.value=groups;}error.value='';demo.value=false;}catch(e){error.value=(e as Error).message;locked.value=/锁定|未安装|未发布/.test(error.value);}finally{loading.value=false;running=false;}}
function start(){if(timer)return;load();timer=setInterval(load,15000);}function stop(){if(timer)clearInterval(timer);timer=undefined;}onBackPress(()=>!!experience.value?.blocking);onMounted(start);onShow(start);onHide(stop);onUnmounted(stop);
</script>
<template><view class="client"><view v-if="loading" class="client-status">正在读取已发布骨架…</view><view v-else-if="locked" class="client-status"><text>{{device}}端未发布骨架，当前锁定。</text><button @click="load">重新检测</button></view><AppExperience v-else ref="experience" :template-key="templateKey" :theme="theme" :items="items" :categories="categories" :section-items="sectionItems" :demo="demo" :error="error" :platform="device" @retry="load"/></view></template>
<style scoped>.client{min-height:100vh;background:#090d16}.client-status{padding:80px 24px;text-align:center;color:#b0bed0;line-height:2}.client-status button{margin-top:20px;max-width:220px}.client :deep(.device-mobile){max-width:600px;margin:0 auto}.client :deep(.experience){height:100vh;height:100dvh}</style>